// The D experience is generated by Pages Functions, not stored as a public HTML asset.
const encoder = new TextEncoder();
const lifetime = 60 * 60 * 8;
const cookieName = '__Host-voxpher-d';

async function signature(secret, value) {
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const bytes = new Uint8Array(await crypto.subtle.sign('HMAC', key, encoder.encode(value)));
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
}
async function same(a, b) {
  const x = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(a)));
  const y = new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(b)));
  let diff = 0;
  for (let i = 0; i < x.length; i++) diff |= x[i] ^ y[i];
  return diff === 0;
}
async function passwordHash(password, salt) {
  const key = await crypto.subtle.importKey('raw', encoder.encode(password), 'PBKDF2', false, ['deriveBits']);
  const bytes = new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2', hash:'SHA-256', salt:encoder.encode(salt), iterations:100000}, key, 256));
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
}
function response(body, status = 200, extra = {}) {
  return new Response(body, {status, headers: {
    'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store, private',
    'X-Robots-Tag': 'noindex, nofollow', 'X-Content-Type-Options': 'nosniff',
    'Content-Security-Policy': "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'",
    ...extra
  }});
}
const css = `<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#160e15;color:#fff7ef;font-family:Georgia,serif;min-height:100svh}body:before{content:'';position:fixed;inset:0;z-index:-1;background:radial-gradient(ellipse at 75% 15%,#843b52 0,transparent 45%),radial-gradient(ellipse at 10% 90%,#563341 0,transparent 42%),#160e15}a{color:inherit}header{display:flex;align-items:center;justify-content:space-between;padding:1.5rem clamp(1.2rem,5vw,4rem);border-bottom:1px solid #ffffff24}header a{text-decoration:none;font:700 .8rem Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase}header .mark{font:italic 2rem Georgia,serif;letter-spacing:0;text-transform:none}main{max-width:1100px;margin:auto;padding:clamp(4rem,12vh,8rem) clamp(1.2rem,6vw,5rem)}.eyebrow{color:#e9a9a4;font:700 .7rem Arial,sans-serif;letter-spacing:.25em;text-transform:uppercase}.hero{max-width:750px;animation:enter 1s ease both}h1{font-size:clamp(3.5rem,11vw,8rem);line-height:.95;font-weight:400;letter-spacing:-.05em;margin:1.4rem 0}h1 em{color:#f0b9aa}p{line-height:1.7;color:#e9d5d2}.intro{max-width:35rem;font-size:clamp(1.05rem,2vw,1.3rem)}.panel{background:#ffffff0b;border:1px solid #ffffff2d;backdrop-filter:blur(16px);padding:clamp(1.4rem,4vw,2.5rem);margin-top:2.5rem}.login{max-width:460px}label{display:block;font:700 .75rem Arial,sans-serif;letter-spacing:.12em;text-transform:uppercase;margin-bottom:.7rem}input{width:100%;padding:1rem;background:#160e15a8;border:1px solid #eac4b899;color:#fff;font-size:1rem}button{cursor:pointer;border:0;background:#f3c9bb;color:#241319;padding:1rem 1.4rem;font:700 .75rem Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;margin-top:1rem}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid white;outline-offset:4px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:3rem}.grid .panel{margin:0;min-height:12rem}.num{font:italic 1rem Georgia;color:#e9a9a4}.grid h2{font-weight:400;font-size:1.7rem}.error{color:#ffc3ba}.foot{margin-top:5rem;color:#caa9a6;font-size:.9rem} @keyframes enter{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}@media(max-width:650px){.grid{grid-template-columns:1fr}.grid .panel{min-height:0}main{padding-top:4rem}}@media(prefers-reduced-motion:reduce){.hero{animation:none}}
</style>`;
function page(content) { return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>D | Voxpher</title>${css}<style>body:after{content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;background-image:radial-gradient(#fff9 1px,transparent 1px);background-size:43px 43px;opacity:.22} .grid .panel{transition:transform .4s ease,box-shadow .4s ease}.grid .panel:hover{transform:translateY(-6px);box-shadow:0 20px 50px #a66c7d26}@media(prefers-reduced-motion:reduce){.hero{animation:none}.grid .panel{transition:none}}</style></head><body><header><a class="mark" href="/">Voxpher</a><a href="/">Back to site ↗</a></header><main>${content}</main></body></html>`; }
function login(error = '') { return page(`<section class="hero"><p class="eyebrow">A little space, just for us</p><h1>For <em>D.</em></h1><p class="intro">Some things are meant to be kept close.</p><form class="panel login" method="post" action="/d"><label for="password">Enter the password</label><input id="password" name="password" type="password" required autocomplete="current-password" maxlength="256">${error ? '<p class="error" role="alert">That password isn’t right. Please try again.</p>' : ''}<button type="submit">Enter this space →</button></form></section>`); }
function inside() { return page(`<style> :root{color-scheme:light}body{background:#fff8fa;color:#5d3947}body:before{background:radial-gradient(ellipse at 85% 10%,#f5d2dd 0,transparent 48%),radial-gradient(ellipse at 10% 90%,#fbe6ec 0,transparent 45%),#fff8fa}header{border-color:#9d64752b}h1 em,.eyebrow,.num{color:#bc778d}p,.foot{color:#80616d}.panel{background:#ffffffb0;border-color:#eacbd5;box-shadow:0 15px 45px #a66c7d12}button{background:#784659;color:#fff}</style><section class="hero"><p class="eyebrow">A space for D</p><h1>Always,<br><em>you.</em></h1><p class="intro">A little place for our favourite moments.</p><div class="grid"><article class="panel"><span class="num">01 /</span><h2>Little moments</h2><p>Memories to keep close.</p></article><article class="panel"><span class="num">02 /</span><h2>Our story</h2><p>Every chapter, in its own time.</p></article><article class="panel"><span class="num">03 /</span><h2>Just because</h2><p>For all the little things.</p></article></div><p class="foot">For D. ♡</p><form method="post" action="/d"><input type="hidden" name="logout" value="1"><button type="submit">Lock this space</button></form></section>`); }
export async function onRequest({request, env}) {
  const secret = env.D_SESSION_SECRET;
  const parts = (env.D_PASSWORD_HASH || '').split(':');
  if (!secret || secret.length < 32 || parts.length !== 2 || !/^[0-9a-f]{32}$/.test(parts[0]) || !/^[0-9a-f]{64}$/.test(parts[1])) return response(page('<p>Private space is not configured yet.</p>'), 503);
  if (request.method === 'POST') {
    const origin = request.headers.get('Origin');
    if (origin && origin !== new URL(request.url).origin) return response('Forbidden', 403);
    let data;
    try { data = await request.formData(); } catch { return response('Bad request', 400); }
    if (data.get('logout') === '1') return new Response(null, {status:303, headers:{Location:'/d', 'Cache-Control':'no-store', 'Set-Cookie':`${cookieName}=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Strict`}});
    const password = data.get('password');
    if (typeof password !== 'string' || password.length > 256 || !(await same(await passwordHash(password, parts[0]), parts[1]))) return response(login(true), 401);
    const expires = String(Math.floor(Date.now() / 1000) + lifetime);
    const token = `${expires}.${await signature(secret, expires)}`;
    return new Response(null, {status:303, headers:{Location:'/d', 'Cache-Control':'no-store', 'Set-Cookie':`${cookieName}=${token}; Path=/; Max-Age=${lifetime}; Secure; HttpOnly; SameSite=Strict`}});
  }
  if (request.method !== 'GET' && request.method !== 'HEAD') return response('Method not allowed', 405, {'Allow':'GET, HEAD, POST'});
  const cookie = (request.headers.get('Cookie') || '').split(';').map(v => v.trim()).find(v => v.startsWith(cookieName + '='));
  const token = cookie ? cookie.slice(cookieName.length + 1).split('.') : [];
  const valid = token.length === 2 && /^\d+$/.test(token[0]) && Number(token[0]) > Date.now() / 1000 && Number(token[0]) <= Date.now() / 1000 + lifetime && await same(token[1], await signature(secret, token[0]));
  return response(valid ? inside() : login());
}
